package com.ellenco.platform.auth;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.net.URI;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.LocalDateTime;import java.util.*;
@Service public class PasswordResetService{private final UserRepository users;private final PasswordResetTokenRepository tokens;private final UserService userService;@Value("${ellenco.app-url:http://localhost:5173}")private String appUrl;@Value("${email.api-key:}")private String apiKey;@Value("${email.from:}")private String from;public PasswordResetService(UserRepository u,PasswordResetTokenRepository t,UserService s){users=u;tokens=t;userService=s;}@Transactional public void request(String email){Optional<User> found=users.findByEmail(email==null?"":email.trim().toLowerCase());if(found.isEmpty())return;String raw=UUID.randomUUID()+"."+UUID.randomUUID();PasswordResetToken token=new PasswordResetToken();token.setUser(found.get());token.setTokenHash(hash(raw));token.setExpiresAt(LocalDateTime.now().plusMinutes(20));tokens.save(token);send(found.get(),raw);}@Transactional public void reset(String raw,String password){PasswordResetToken token=tokens.findByTokenHash(hash(raw)).orElseThrow(()->new IllegalArgumentException("Link inválido ou expirado."));if(token.getUsedAt()!=null||token.getExpiresAt().isBefore(LocalDateTime.now()))throw new IllegalArgumentException("Link inválido ou expirado.");userService.updatePassword(token.getUser(),password);token.setUsedAt(LocalDateTime.now());tokens.save(token);}private void send(User user,String raw){if(apiKey.isBlank()||from.isBlank())throw new IllegalStateException("Serviço de e-mail ainda não configurado.");String link=appUrl+"/?resetToken="+raw;String json="{\"from\":\""+esc(from)+"\",\"to\":[\""+esc(user.getEmail())+"\"],\"subject\":\"Recuperação de acesso ELLENCO\",\"html\":\"<h2>Recuperação de acesso</h2><p>Olá, "+esc(user.getNome())+".</p><p><a href='"+esc(link)+"'>Criar nova senha</a></p><p>O link expira em 20 minutos.</p>\"}";try{HttpRequest req=HttpRequest.newBuilder(URI.create("https://api.resend.com/emails")).header("Authorization","Bearer "+apiKey).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json)).build();HttpResponse<String> response=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString());if(response.statusCode()/100!=2)throw new IllegalStateException("Falha ao enviar e-mail.");}catch(Exception e){throw new IllegalStateException("Não foi possível enviar o e-mail de recuperação.");}}private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private String esc(String v){return v.replace("\\","\\\\").replace("\"","\\\"");}}
